	@ParameterizedTest
	@EnumSource(RowReuse.class)
	void repositoryBatchSnapshotsReusedSourceContainers(RowReuse reuse, @TempDir File directory) {
		seed(directory, 17);
		ProbeSail probe = new ProbeSail(newStore(directory), -1, reuse);
		SailRepository repository = new SailRepository(probe);
		repository.init();
		List<Long> retainedIds = new ArrayList<>();
		try (RepositoryConnection connection = repository.getConnection()) {
			if (reuse == RowReuse.BINDINGS) {
				List<BindingSet> retained = new ArrayList<>();
				try (TupleQueryResult result = connection.prepareTupleQuery(SELECT).evaluate()) {
					while (result.hasNext()) {
						BindingSet row = result.next();
						assertDeepReady(row.getValue("value"));
						retained.add(row);
					}
				}
				retained.forEach(row -> retainedIds.add(((LmdbValue) row.getValue("value")).getInternalID()));
			} else {
				List<Statement> retained = new ArrayList<>();
				try (RepositoryResult<Statement> result = connection.getStatements(null, null, null, false)) {
					while (result.hasNext()) {
						Statement row = result.next();
						assertDeepReady(row.getObject());
						retained.add(row);
					}
				}
				retained.forEach(row -> retainedIds.add(((LmdbValue) row.getObject()).getInternalID()));
			}
			assertEquals(17, retainedIds.size());
			assertEquals(probe.sourceIds, retainedIds,
					"A source may reuse its row container; buffered outward rows must retain their own values");
		} finally {
			repository.shutDown();
		}
	}

